{
  "$schema": "vscode://schemas/tasks",
  "version": "2.0.0",
  "inputs": [
    {
      "id": "rgSearchQuery",
      "type": "promptString",
      "description": "Enter the ripgrep query (regex or literal) to search for",
      "default": ""
    }
  ],
  // TODO: split VS Code tasks into grouped include files or generate tasks from scripts.
  "tasks": [
    {
      "label": "🤖 LangGraph NATS Worker",
      "type": "shell",
      "command": "node scripts/startup/ensure-nats-langgraph.mjs",
      "options": {
        "cwd": "${workspaceFolder}/sveltekit-frontend"
      },
      "isBackground": true,
      "runOptions": {
        "runOn": "folderOpen"
      },
      "problemMatcher": []
    },
    {
      "label": "Dev Server",
      "type": "shell",
      "command": "npm run dev",
      "options": {
        "cwd": "${workspaceFolder}/sveltekit-frontend"
      },
      "isBackground": true,
      "group": {
        "kind": "build",
        "isDefault": true
      },
      "problemMatcher": {
        "owner": "vite",
        "pattern": {
          "regexp": "^([^\\s].*):(\\d+):(\\d+):\\s+(warning|error):\\s+(.*)$",
          "file": 1,
          "line": 2,
          "column": 3,
          "severity": 4,
          "message": 5
        },
        "background": {
          "activeOnStart": true,
          "beginsPattern": ".",
          "endsPattern": "ready in"
        }
      },
      "presentation": {
        "echo": true,
        "reveal": "always",
        "focus": false,
        "panel": "dedicated",
        "showReuseMessage": false,
        "clear": true
      }
    },
    {
      "label": "Dev Server (GPU, detached)",
      "type": "shell",
      "command": "node scripts/startup/run-detached.mjs dev:gpu",
      "options": {
        "cwd": "${workspaceFolder}/sveltekit-frontend"
      },
      "runOptions": {
        "runOn": "folderOpen"
      },
      "group": "build",
      "problemMatcher": [],
      "presentation": {
        "echo": true,
        "reveal": "always",
        "focus": false,
        "panel": "dedicated",
        "showReuseMessage": false,
        "clear": false
      },
      "detail": "AUTO-STARTS on folder open — spawns npm run dev:gpu detached so VS Code returns immediately. Uses scripts/startup/run-detached.mjs and writes logs to logs/task-output/pipeline-test/dev-gpu.{out,err}.log."
    },
    {
      "label": "Dev Server (gRPC Retrieval)",
      "type": "shell",
      "command": "npm run dev:grpc",
      "options": {
        "cwd": "${workspaceFolder}/sveltekit-frontend"
      },
      "isBackground": true,
      "group": "build",
      "problemMatcher": {
        "owner": "vite",
        "pattern": {
          "regexp": "^([^\\s].*):(\\d+):(\\d+):\\s+(warning|error):\\s+(.*)$",
          "file": 1,
          "line": 2,
          "column": 3,
          "severity": 4,
          "message": 5
        },
        "background": {
          "activeOnStart": true,
          "beginsPattern": ".",
          "endsPattern": "ready in"
        }
      },
      "presentation": {
        "echo": true,
        "reveal": "always",
        "focus": false,
        "panel": "dedicated",
        "showReuseMessage": false,
        "clear": true
      },
      "detail": "Start TurboQuant llama-server (gemma4-rotorquant:latest + mmproj VLM on :8090), Go retrieval gRPC (:50053), and the GPU-optimized frontend dev server (:5173)"
    },
    {
      "label": "TurboQuant llama-server (VLM)",
      "type": "shell",
      "command": "npm run turbo:start:detached",
      "options": {
        "cwd": "${workspaceFolder}/sveltekit-frontend"
      },
      "group": "build",
      "problemMatcher": [],
      "presentation": {
        "echo": true,
        "reveal": "always",
        "focus": false,
        "panel": "dedicated",
        "showReuseMessage": false,
        "clear": true
      },
      "detail": "Spawn TurboQuant llama-server.exe as a detached PowerShell child, wait for /health on :8090, and return immediately. Uses stable q8_0 KV cache, 64K ctx, and adds mmproj automatically if present."
    },
    {
      "label": "MCP TRACE Server (detached)",
      "type": "shell",
      "command": "npm run mcp:ensure",
      "options": {
        "cwd": "${workspaceFolder}/sveltekit-frontend"
      },
      "group": "build",
      "problemMatcher": [],
      "presentation": {
        "echo": true,
        "reveal": "silent",
        "focus": false,
        "panel": "dedicated",
        "showReuseMessage": false,
        "clear": false
      },
      "detail": "Spawn trace-mcp-server.ts detached (same pattern as TurboQuant), idempotent — health-checks :8788 first and returns immediately if already alive. Required by Gemma4 agent + clusters.get_members + 35-tool MCP surface."
    },
    {
      "label": "🧪 MCP JSON-RPC 2.0 Verification",
      "type": "shell",
      "command": "node scripts/verify-mcp-json-rpc.mjs",
      "options": {
        "cwd": "${workspaceFolder}"
      },
      "group": "test",
      "problemMatcher": [],
      "presentation": {
        "echo": true,
        "reveal": "always",
        "focus": false,
        "panel": "dedicated",
        "showReuseMessage": false,
        "clear": true
      },
      "detail": "Verify the unified MCP JSON-RPC 2.0 pipeline is working. Tests TRACE MCP :8788/mcp responds to tools/list and tools/call JSON-RPC requests. Run after 'MCP TRACE Server (detached)' starts."
    },
    {
      "label": "Agents Pipeline (Safe)",
      "type": "shell",
      "command": "npm run agents:pipeline:safe",
      "options": {
        "cwd": "${workspaceFolder}/sveltekit-frontend"
      },
      "group": "build",
      "problemMatcher": [],
      "presentation": {
        "echo": true,
        "reveal": "always",
        "focus": false,
        "panel": "dedicated",
        "showReuseMessage": false,
        "clear": true
      },
      "detail": "Run agents:write → agents:enrich → agents:index → smoke:agents with a dry-run preflight. Uses size-shrink + read-error fail-closed safeguards. Backups to .bak when |new − old| > 2KB."
    },
    {
      "label": "Agents Pipeline (Dry-Run Only)",
      "type": "shell",
      "command": "npm run agents:pipeline:dry",
      "options": {
        "cwd": "${workspaceFolder}/sveltekit-frontend"
      },
      "group": "test",
      "problemMatcher": [],
      "presentation": {
        "echo": true,
        "reveal": "always",
        "focus": false,
        "panel": "dedicated",
        "showReuseMessage": false,
        "clear": true
      },
      "detail": "Preview AGENTS.md changes without writing. Useful before committing — shows TODO-enhancements.md diff + per-directory enrich plan."
    },
    {
      "label": "GraphRAG Index Loop (Dry-Run)",
      "type": "shell",
      "command": "node scripts/index-graphrag-loop.mjs --dry-run",
      "options": {
        "cwd": "${workspaceFolder}/sveltekit-frontend"
      },
      "group": "test",
      "problemMatcher": [],
      "presentation": {
        "echo": true,
        "reveal": "always",
        "focus": false,
        "panel": "dedicated",
        "showReuseMessage": false,
        "clear": true
      },
      "detail": "Preview the canonical graphRAG loop without duplicating GPU indexing or Atlas writes."
    },
    {
      "label": "GraphRAG Index Loop",
      "type": "shell",
      "command": "node scripts/index-graphrag-loop.mjs",
      "options": {
        "cwd": "${workspaceFolder}/sveltekit-frontend"
      },
      "group": "build",
      "problemMatcher": [],
      "presentation": {
        "echo": true,
        "reveal": "always",
        "focus": false,
        "panel": "dedicated",
        "showReuseMessage": false,
        "clear": true
      },
      "detail": "Run the canonical graphRAG loop manually. No folderOpen auto-start, so GPU indexing stays single-sourced."
    },
    {
      "label": "Messy Query Routing Evaluation",
      "type": "shell",
      "command": "npm run atlas:messy-routing",
      "options": {
        "cwd": "${workspaceFolder}"
      },
      "group": "test",
      "problemMatcher": [],
      "presentation": {
        "echo": true,
        "reveal": "always",
        "focus": false,
        "panel": "dedicated",
        "showReuseMessage": false,
        "clear": true
      },
      "detail": "Run Phase 18 messy query router evaluation and write reports to docs/reports."
    },
    {
      "label": "Messy Query Routing (custom)",
      "type": "shell",
      "command": "npm run atlas:messy-routing -- --query \"${input:messyRoutingQuery}\"",
      "options": {
        "cwd": "${workspaceFolder}"
      },
      "group": "test",
      "problemMatcher": [],
      "presentation": {
        "echo": true,
        "reveal": "always",
        "focus": false,
        "panel": "dedicated",
        "showReuseMessage": false,
        "clear": true
      },
      "detail": "Run Phase 18 messy query router evaluation with a custom query prompt."
    },
    {
      "label": "Search Repo Docs with rg",
      "type": "shell",
      "command": "powershell",
      "args": [
        "-NoProfile",
        "-ExecutionPolicy",
        "Bypass",
        "-Command",
        "if (-not \"${input:rgSearchQuery}\") { Write-Error 'Query required'; exit 1 }; rg -n --glob '!node_modules' \"${input:rgSearchQuery}\" docs ."
      ],
      "options": {
        "cwd": "${workspaceFolder}"
      },
      "group": "test",
      "problemMatcher": [],
      "presentation": {
        "echo": true,
        "reveal": "always",
        "focus": true,
        "panel": "dedicated",
        "showReuseMessage": false,
        "clear": true
      },
      "detail": "Prompt for a ripgrep query and search repo docs plus root files for matching references."
    },
    {
      "label": "Search SvelteKit App Docs with rg",
      "type": "shell",
      "command": "powershell",
      "args": [
        "-NoProfile",
        "-ExecutionPolicy",
        "Bypass",
        "-Command",
        "if (-not \"${input:rgSearchQuery}\") { Write-Error 'Query required'; exit 1 }; rg -n --glob '!node_modules' \"${input:rgSearchQuery}\" sveltekit-frontend/docs sveltekit-frontend/src"
      ],
      "options": {
        "cwd": "${workspaceFolder}"
      },
      "group": "test",
      "problemMatcher": [],
      "presentation": {
        "echo": true,
        "reveal": "always",
        "focus": true,
        "panel": "dedicated",
        "showReuseMessage": false,
        "clear": true
      },
      "detail": "Prompt for a ripgrep query and search the SvelteKit app docs + source files."
    },
    {
      "label": "📚 Docs: Refresh Programming Hub (web+rg)",
      "type": "shell",
      "command": "npm run docs:programming:refresh",
      "options": {
        "cwd": "${workspaceFolder}/sveltekit-frontend"
      },
      "group": "test",
      "problemMatcher": [],
      "presentation": {
        "echo": true,
        "reveal": "always",
        "focus": false,
        "panel": "dedicated",
        "showReuseMessage": false,
        "clear": true
      },
      "detail": "Fetch latest docs (Bifrost, Firecrawl, Redis, WebGPU, CUDA, cuVS, Go, Drizzle, UnoCSS, Bits UI, shadcn-svelte) and merge with repo rg mappings."
    },
    {
      "label": "✅ KAG: Phase 0/1/8 Gate (JSON)",
      "type": "shell",
      "command": "npm run kag:phase-gate",
      "options": {
        "cwd": "${workspaceFolder}/sveltekit-frontend"
      },
      "group": "test",
      "problemMatcher": [],
      "presentation": {
        "echo": true,
        "reveal": "always",
        "focus": true,
        "panel": "dedicated",
        "showReuseMessage": false,
        "clear": true
      },
      "detail": "Runs checklist Phase 0/1/8 health + memory + Bifrost boundary checks and writes docs/reports/kag-phase-gate-latest.json."
    },
    {
      "label": "ACE: TurboVec Sidecar :8791 (Python, detached)",
      "type": "shell",
      "command": "pwsh -NoProfile -Command \"$p = Get-NetTCPConnection -LocalPort 8791 -ErrorAction SilentlyContinue; if ($p) { Write-Host '⚡ TurboVec sidecar already running on :8791' } else { Start-Process python -ArgumentList 'scripts/ingest/turbovec-sidecar.py' -WorkingDirectory '${workspaceFolder}' -WindowStyle Hidden; Start-Sleep 2; $h = Invoke-RestMethod http://127.0.0.1:8791/health -ErrorAction SilentlyContinue; if ($h.status -eq 'ok') { Write-Host '⚡ TurboVec sidecar started :8791 OK' } else { Write-Host '⚠️ TurboVec sidecar may not have started — check manually' } }\"",
      "options": { "cwd": "${workspaceFolder}" },
      "group": "build",
      "problemMatcher": [],
      "runOptions": { "runOn": "folderOpen" },
      "presentation": { "echo": true, "reveal": "silent", "focus": false, "panel": "shared", "showReuseMessage": false, "clear": false },
      "detail": "Start the TurboVec Python ANN sidecar on :8791 (detached, idempotent — skips if already running). Used by rerank-cards.mjs for 2-bit quantized vector search over ACE packet embeddings."
    },
    {
      "label": "ACE: Stub + Rank + Rerank + Recommend (full pipeline)",
      "type": "shell",
      "command": "pwsh -NoProfile -Command \"`$stamp = 'logs/task-output/.ace-startup-last-run'; `$cooldownSec = 3600; if ((Test-Path `$stamp) -and ((Get-Date) - (Get-Item `$stamp).LastWriteTime).TotalSeconds -lt `$cooldownSec) { Write-Host ('ACE pipeline skipped — last run ' + [int]((Get-Date) - (Get-Item `$stamp).LastWriteTime).TotalMinutes + ' min ago (1h cooldown)') } else { New-Item -Path logs/task-output -ItemType Directory -Force | Out-Null; npm run ace:startup 2>&1 | Tee-Object logs/task-output/ace-startup-latest.log; if (`$LASTEXITCODE -eq 0) { Set-Content -Path `$stamp -Value (Get-Date -Format o); Write-Host 'ACE startup pipeline green' } else { Write-Host 'ACE startup pipeline FAILED — check logs/task-output/ace-startup-latest.log' } }\"",
      "options": { "cwd": "${workspaceFolder}" },
      "group": "build",
      "problemMatcher": [],
      "runOptions": { "runOn": "folderOpen" },
      "presentation": { "echo": true, "reveal": "silent", "focus": false, "panel": "shared", "showReuseMessage": false, "clear": false },
      "detail": "On folder open: stub missing embeddings → rank-cards → rerank-cards (TurboVec) → compress-cards → build-recommendations → feature-labeling → domain-topology → intent-cache → cache-ace-packet → materialize-tasks. 1h cooldown stamp. Logs to logs/task-output/ace-startup-latest.log."
    },
    {
      "label": "ACE Cache Index Refresh",
      "type": "shell",
      "command": "npm run ace:cache:index:refresh",
      "options": {
        "cwd": "${workspaceFolder}/sveltekit-frontend"
      },
      "group": "build",
      "problemMatcher": [],
      "presentation": {
        "echo": true,
        "reveal": "always",
        "focus": false,
        "panel": "dedicated",
        "showReuseMessage": false,
        "clear": true
      },
      "detail": "Refresh ACE cache indexing via Postgres chunk_id sync, demand seeding, Qdrant cluster keys, and cluster aggregation."
    },
    {
      "label": "Qdrant: Backfill Cluster Keys (gpu: namespace)",
      "type": "shell",
      "command": "npm run qdrant:backfill-cluster-keys",
      "options": {
        "cwd": "${workspaceFolder}/sveltekit-frontend"
      },
      "group": "build",
      "problemMatcher": [],
      "presentation": {
        "echo": true,
        "reveal": "always",
        "focus": false,
        "panel": "dedicated",
        "showReuseMessage": false,
        "clear": true
      },
      "detail": "Patch cluster_key payload in codebase_chunks_768 to use the gpu:N namespace MCP queries with. Uses Qdrant SetPayload (only touches cluster_key + agents_scope + relation_types — vector and content stay intact). Idempotent: skips already-correct rows."
    },
    {
      "label": "Agents: DB Verify (manual)",
      "type": "shell",
      "command": "npm run agents:db:verify",
      "options": {
        "cwd": "${workspaceFolder}/sveltekit-frontend"
      },
      "group": "test",
      "problemMatcher": [],
      "presentation": {
        "echo": true,
        "reveal": "always",
        "focus": true,
        "panel": "dedicated",
        "showReuseMessage": false,
        "clear": true
      },
      "detail": "Read-only check that AGENTS.md Postgres mirror tables exist (agent_context_files, directory_context_bindings, ace_context_sources) and report row counts. Run AFTER applying drizzle/manual/agents_md_relations.sql. Schema migrations are deliberate operator actions — never auto-run on folder open."
    },
    {
      "label": "Backend Stack (MCP + TurboQuant detached)",
      "dependsOn": [
        "MCP TRACE Server (detached)",
        "TurboQuant llama-server (VLM)"
      ],
      "dependsOrder": "parallel",
      "problemMatcher": [],
      "presentation": {
        "echo": true,
        "reveal": "silent",
        "focus": false,
        "panel": "shared",
        "showReuseMessage": false,
        "clear": false
      },
      "detail": "Start MCP TRACE (:8788) and TurboQuant llama-server (:8090) in parallel. Both detached — VS Code returns immediately. Frontend dev server is started separately."
    },
    {
      "label": "Agentic Stack: Ensure MCP + TurboQuant + Topology",
      "dependsOn": [
        "MCP TRACE Server (detached)",
        "TurboQuant llama-server (VLM)",
        "Topology Search: Ensure"
      ],
      "dependsOrder": "parallel",
      "problemMatcher": [],
      "presentation": {
        "echo": true,
        "reveal": "silent",
        "focus": false,
        "panel": "shared",
        "showReuseMessage": false,
        "clear": false
      },
      "detail": "Bring up the orchestration plane (MCP), inference plane (TurboQuant llama-server), and retrieval topology plane. Use before Gemma4 agentic tool-calling tests."
    },
    {
      "label": "RTX Pipeline: TurboVec ANN Sidecar (detached)",
      "type": "shell",
      "command": "node scripts/startup/run-detached.mjs turbovec:sidecar",
      "options": {
        "cwd": "${workspaceFolder}/sveltekit-frontend"
      },
      "group": "build",
      "problemMatcher": [],
      "presentation": {
        "echo": true,
        "reveal": "silent",
        "focus": false,
        "panel": "shared",
        "showReuseMessage": false,
        "clear": false
      },
      "detail": "Spawn TurboVec ANN wrapper on :8792 (detached). It spawns the RotorQuant helper on :8793 when available, scrolls codebase_chunks_768 from Qdrant, builds 4-bit quantized index for ultra-fast HyperRAG candidate prefilter. Logs → logs/task-output/pipeline-test/turbovec-sidecar.{out,err}.log. Health: GET http://127.0.0.1:8792/health"
    },
    {
      "label": "RTX Pipeline: Semantic Cluster (4D Manifold to Redis)",
      "type": "shell",
      "command": "npm run graphify:semantic-cluster",
      "options": {
        "cwd": "${workspaceFolder}/sveltekit-frontend"
      },
      "group": "build",
      "problemMatcher": [],
      "presentation": {
        "echo": true,
        "reveal": "always",
        "focus": false,
        "panel": "dedicated",
        "showReuseMessage": false,
        "clear": true
      },
      "detail": "Run GPU k-means on glyph_atlas Qdrant collection → write cluster centroids + 4D manifold topology to Redis (cluster:kmeans:k20:*). Required to activate cluster-prefiltered HyperRAG multi-query. OOM-hardened: server-side Qdrant filter + minimal payload fields."
    },
    {
      "label": "RTX Pipeline: HyperRAG Multi-Query (dry-run)",
      "type": "shell",
      "command": "node scripts/hyperrag-dense-multiquery.mjs --query \"retrieval context assembler pipeline\" --dry-run",
      "options": {
        "cwd": "${workspaceFolder}/sveltekit-frontend"
      },
      "group": "test",
      "problemMatcher": [],
      "presentation": {
        "echo": true,
        "reveal": "always",
        "focus": true,
        "panel": "dedicated",
        "showReuseMessage": false,
        "clear": true
      },
      "detail": "Run HyperRAG dense multi-query: embed → TurboVec ANN prefilter → 4D manifold cluster filter → Qdrant semantic+kag lanes → RRF merge + PageRank boost → CouchDB wiki enrichment. Output: logs/hyperrag-stream/latest.json (Bifrost inference stream / rotorquant feed)."
    },
    {
      "label": "RTX Pipeline: HyperRAG Custom Query",
      "type": "shell",
      "command": "node scripts/hyperrag-dense-multiquery.mjs --query \"${input:hyperragQuery}\"",
      "options": {
        "cwd": "${workspaceFolder}/sveltekit-frontend"
      },
      "group": "test",
      "problemMatcher": [],
      "presentation": {
        "echo": true,
        "reveal": "always",
        "focus": true,
        "panel": "dedicated",
        "showReuseMessage": false,
        "clear": true
      },
      "detail": "Run HyperRAG dense multi-query with a custom query string. Prompts for query text. Result feeds the Bifrost inference stream via logs/hyperrag-stream/latest.json."
    },
    {
      "label": "RTX Pipeline: Full Startup (TurboVec + Cluster + Smoke)",
      "dependsOn": [
        "RTX Pipeline: TurboVec ANN Sidecar (detached)",
        "RTX Pipeline: Semantic Cluster (4D Manifold to Redis)"
      ],
      "dependsOrder": "sequence",
      "group": "build",
      "problemMatcher": [],
      "presentation": {
        "echo": true,
        "reveal": "always",
        "focus": false,
        "panel": "shared",
        "showReuseMessage": false,
        "clear": false
      },
      "detail": "Full RTX pipeline startup: spawn TurboVec sidecar (detached), then rebuild 4D manifold cluster topology in Redis. After this, hyperrag:multiquery will use ANN prefilter + cluster routing automatically."
    },
    {
      "label": "Topology Search: Ensure",
      "type": "shell",
      "command": "npm run topology:search:ensure",
      "options": {
        "cwd": "${workspaceFolder}/sveltekit-frontend"
      },
      "group": "build",
      "problemMatcher": [],
      "presentation": {
        "echo": true,
        "reveal": "silent",
        "focus": false,
        "panel": "dedicated",
        "showReuseMessage": false,
        "clear": false
      },
      "detail": "Start or health-check the topology retrieval service used for 4D/SOM neighborhood search. This is the vector/topology retrieval plane, not inference."
    },
    {
      "label": "Gemma4 Agentic Tool Calling: Smoke Full Loop",
      "type": "shell",
      "command": "npm run smoke:trace:full",
      "options": {
        "cwd": "${workspaceFolder}/sveltekit-frontend"
      },
      "group": "test",
      "problemMatcher": [],
      "presentation": {
        "echo": true,
        "reveal": "always",
        "focus": true,
        "panel": "dedicated",
        "showReuseMessage": false,
        "clear": true
      },
      "detail": "End-to-end Gemma4/MCP loop smoke. Verifies that the model-facing orchestration plane can call tools and synthesize from returned context."
    },
    {
      "label": "Gemma4 Agentic Tool Calling: Tool Surface Audit",
      "type": "shell",
      "command": "node scripts/smoke-trace-mcp-tools.mjs",
      "options": {
        "cwd": "${workspaceFolder}/sveltekit-frontend"
      },
      "group": "test",
      "problemMatcher": [],
      "presentation": {
        "echo": true,
        "reveal": "always",
        "focus": true,
        "panel": "dedicated",
        "showReuseMessage": false,
        "clear": true
      },
      "detail": "Read-only audit of the MCP tool registry on :8788. Use when changing graph, KB, topology, web, or fix-attempt tools."
    },
    {
      "label": "Retrieval Plane: Fast Graph + Topology Refresh",
      "type": "shell",
      "command": "npm run graphify:intel:fast",
      "options": {
        "cwd": "${workspaceFolder}/sveltekit-frontend"
      },
      "group": "build",
      "problemMatcher": [],
      "presentation": {
        "echo": true,
        "reveal": "always",
        "focus": false,
        "panel": "dedicated",
        "showReuseMessage": false,
        "clear": true
      },
      "detail": "Refresh sparse graph, topology payloads, wiki enrichment, and graphify smoke. This feeds retrieval; it does not run the LLM as the search engine."
    },
    {
      "label": "Retrieval Plane: Karpathy GPU Rank Refresh",
      "type": "shell",
      "command": "npm run karpathy:gpu",
      "options": {
        "cwd": "${workspaceFolder}/sveltekit-frontend"
      },
      "group": "build",
